('500001', '5001', 'Senso-ji Temple', 'Senso-ji Temple', 'Tokyo''s oldest and best-known Buddhist temple, centered on Kaminarimon, Nakamise shopping street and the main hall.', '1-2 hours', 'Morning', '', '', 'Tokyo', 0, 0, '', '', 'Check current admission / free where public', 5.0, 4.9, NULL, NULL, 'Senso-ji Temple, Tokyo, Japan', 'https://www.japan.travel/en/spot/1698/', 0.95, '2026-10-01 20:35:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 20:35:00', 'verified', 'Established attraction; current hours, fees and access rules should be refreshed before production.', '2026-10-01'),
('500002', '5001', 'Nakamise Shopping Street', 'Nakamise Shopping Street', 'Historic approach to Senso-ji lined with traditional snack, craft and souvenir shops.', '1-2 hours', 'Morning', '', '', 'Tokyo', 0, 0, '', '', 'Check current admission / free where public', 4.8, 4.7, NULL, NULL, 'Nakamise Shopping Street, Tokyo, Japan', NULL, 0.93, '2026-10-01 20:35:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 20:35:00', 'verified', 'Established attraction; current hours, fees and access rules should be refreshed before production.', '2026-10-01'),
('500003', '5001', 'Tokyo Skytree', 'Tokyo Skytree', '634-metre broadcasting tower with two observation levels and wide views across Tokyo and, on clear days, Mt. Fuji.', '1-2 hours', 'Morning', '', '', 'Tokyo', 0, 0, '', '', 'Ticketed; date and deck combination affect price', 5.0, 4.8, NULL, NULL, 'Tokyo Skytree, Tokyo, Japan', 'https://www.tokyo-skytree.jp/', 0.95, '2026-10-01 20:35:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 20:35:00', 'verified', 'Official 2026 operating-calendar pages show date-specific hours. Late Sep/Oct examples are commonly 9 or 10 AM-10 PM with last admission at 9 PM; special dates can differ.', '2026-10-01'),
('500004', '5001', 'Meiji Jingu', 'Meiji Jingu', 'Forest shrine dedicated to Emperor Meiji and Empress Shoken, reached through broad torii-lined approaches in Shibuya.', '1-2 hours', 'Morning', '', '', 'Tokyo', 0, 0, '', '', 'Check current admission / free where public', 5.0, 4.9, NULL, NULL, 'Meiji Jingu, Tokyo, Japan', 'https://www.meijijingu.or.jp/en/', 0.95, '2026-10-01 20:35:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 20:35:00', 'verified', 'Established attraction; current hours, fees and access rules should be refreshed before production.', '2026-10-01'),
('500005', '5001', 'Harajuku Takeshita Street', 'Harajuku Takeshita Street', 'Youth-fashion pedestrian street with boutiques, sweets and pop-culture shopping.', '1-2 hours', 'Morning', '', '', 'Tokyo', 0, 0, '', '', 'Check current admission / free where public', 4.6, 4.4, NULL, NULL, 'Harajuku Takeshita Street, Tokyo, Japan', NULL, 0.92, '2026-10-01 20:35:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 20:35:00', 'verified', 'Established attraction; current hours, fees and access rules should be refreshed before production.', '2026-10-01'),
('500006', '5001', 'Shibuya Scramble Crossing', 'Shibuya Scramble Crossing', 'Iconic multi-direction pedestrian crossing surrounded by screens and high-rise viewpoints.', '1-2 hours', 'Morning', '', '', 'Tokyo', 0, 0, '', '', 'Free', 5.0, 4.7, NULL, NULL, 'Shibuya Scramble Crossing, Tokyo, Japan', NULL, 0.95, '2026-10-01 20:35:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 20:35:00', 'verified', 'Established attraction; current hours, fees and access rules should be refreshed before production.', '2026-10-01'),
