('500161', '5009', 'Hiroshima Peace Memorial Park', 'Hiroshima Peace Memorial Park', 'Memorial park centered on the legacy of the atomic bombing, including museums, monuments and the cenotaph.', '1-2 hours', 'Morning', '', '', 'Hiroshima', 0, 0, '', '', 'Free park access', 5.0, 5.0, NULL, NULL, 'Hiroshima Peace Memorial Park, Hiroshima, Japan', NULL, 0.95, '2026-10-01 20:35:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 20:35:00', 'verified', 'Established attraction; current hours, fees and access rules should be refreshed before production.', '2026-10-01'),
('500162', '5009', 'Atomic Bomb Dome', 'Atomic Bomb Dome', 'UNESCO-preserved ruin of the former Industrial Promotion Hall, now a global peace symbol.', '1-2 hours', 'Morning', '', '', 'Hiroshima', 0, 0, '', '', 'Free', 5.0, 5.0, NULL, NULL, 'Atomic Bomb Dome, Hiroshima, Japan', NULL, 0.95, '2026-10-01 20:35:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 20:35:00', 'verified', 'Established attraction; current hours, fees and access rules should be refreshed before production.', '2026-10-01'),
('500163', '5009', 'Hiroshima Peace Memorial Museum', 'Hiroshima Peace Memorial Museum', 'Museum documenting the atomic bombing, victims'' experiences and the movement for nuclear abolition.', '1-2 hours', 'Morning', '', '', 'Hiroshima', 0, 0, '', '', 'Check current admission / free where public', 5.0, 5.0, NULL, NULL, 'Hiroshima Peace Memorial Museum, Hiroshima, Japan', 'https://hpmmuseum.jp/?lang=eng', 0.95, '2026-10-01 20:35:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 20:35:00', 'verified', 'Established attraction; current hours, fees and access rules should be refreshed before production.', '2026-10-01'),
('500164', '5009', 'Children''s Peace Monument', 'Children''s Peace Monument', 'Memorial inspired by Sadako Sasaki and dedicated to children affected by the atomic bombing.', '1-2 hours', 'Morning', '', '', 'Hiroshima', 0, 0, '', '', 'Free', 4.7, 4.8, NULL, NULL, 'Children''s Peace Monument, Hiroshima, Japan', NULL, 0.93, '2026-10-01 20:35:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 20:35:00', 'verified', 'Established attraction; current hours, fees and access rules should be refreshed before production.', '2026-10-01'),
('500165', '5009', 'Hiroshima Castle', 'Hiroshima Castle', 'Reconstructed castle complex and grounds associated with Hiroshima''s feudal history.', '1-2 hours', 'Morning', '', '', 'Hiroshima', 0, 0, '', '', 'Check current admission / free where public', 4.5, 4.5, NULL, NULL, 'Hiroshima Castle, Hiroshima, Japan', NULL, 0.91, '2026-10-01 20:35:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 20:35:00', 'partial', 'Established attraction; current hours, fees and access rules should be refreshed before production.', '2026-10-01'),
